import hash from 'object-hash';
import { v4 as uuidv4 } from 'uuid';
import { getComponentNameFromRef } from '../componentRefs.js';
import { mapExample } from './mapExample.js';
import { mapSchema } from './mapSchema.js';
export const mapMedia = ({ content, refUuidMap, uuidObjectHashMap, hashedNodeMap, uuid, }) => {
    const objectHash = hash(content);
    uuidObjectHashMap[uuid] = objectHash;
    // if we've seen this exact object before, skip processing
    if (objectHash in hashedNodeMap) {
        return;
    }
    if ('$ref' in content && typeof content.$ref === 'string') {
        const name = getComponentNameFromRef(content.$ref, 'mediaTypes');
        const refId = name === undefined ? content.$ref : `#/components/mediaTypes/${name}`;
        const mediaRef = Object.assign(Object.assign({}, content), { $ref: refUuidMap[refId] || uuidv4() });
        hashedNodeMap[objectHash] = mediaRef;
        return;
    }
    const ownReference = (node) => typeof node === 'object' && node !== null && '$ref' in node ? Object.assign({}, node) : node;
    const media = Object.assign(Object.assign({}, content), ('examples' in content && content.examples
        ? {
            examples: Object.fromEntries(Object.entries(content.examples).map(([name, example]) => [name, ownReference(example)])),
        }
        : {}));
    if ('schema' in media)
        media.schema = ownReference(media.schema);
    if ('itemSchema' in media)
        media.itemSchema = ownReference(media.itemSchema);
    // if schema in media, create SchemaOrRef node
    if ('schema' in media && media.schema && typeof media.schema === 'object') {
        const uuid = uuidv4();
        mapSchema({ schema: media.schema, refUuidMap, uuidObjectHashMap, hashedNodeMap, uuid });
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        media.schema = uuid;
    }
    if ('itemSchema' in media && media.itemSchema && typeof media.itemSchema === 'object') {
        const uuid = uuidv4();
        mapSchema({ schema: media.itemSchema, refUuidMap, uuidObjectHashMap, hashedNodeMap, uuid });
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        media.itemSchema = uuid;
    }
    // if examples in media, create ExampleOrRef node
    if ('examples' in media && media.examples && typeof media.examples === 'object') {
        Object.entries(media.examples).forEach(([exampleName, example]) => {
            const uuid = uuidv4();
            mapExample({ example, refUuidMap, uuidObjectHashMap, hashedNodeMap, uuid });
            if (media.examples) {
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                media.examples[exampleName] = uuid;
            }
        });
    }
    // if encoding in media, create Encoding node
    // TODO: add support for encoding
    // add to hashedNodeMap
    hashedNodeMap[objectHash] = media;
};
